def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water = int(my_status['no_water_days'])

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    opp_budgets = []
    desperate_count = 0
    rich_count = 0
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            ob = float(opp.get('budget', 0.0))
            opp_budgets.append(ob)
            if ob < DAILY_SALARY * 1.2:
                desperate_count += 1
            if ob > DAILY_SALARY * 3.0:
                rich_count += 1
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                try:
                    prev_bids.append(float(bid))
                except Exception:
                    pass

    if not alive:
        return float(min(budget, 15.0 if hp > 4 else 35.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0
    max_opp_budget = max(opp_budgets) if opp_budgets else 0.0

    scarcity = (MAX_SUPPLY_PLACEHOLDER := 25)
    scarcity_score = (25.0 - supply) / 10.0
    if scarcity_score < 0:
        scarcity_score = 0.0
    if scarcity_score > 1.0:
        scarcity_score = 1.0

    urgency = 0.0
    if hp <= 2:
        urgency += 1.0
    elif hp <= 4:
        urgency += 0.55
    if no_water >= 2:
        urgency += 1.0
    elif no_water == 1:
        urgency += 0.45
    urgency += scarcity_score * 0.7

    if hp <= 2 or no_water >= 2:
        target = max(highest_prev + 3.0, DAILY_SALARY * (1.15 + 0.25 * scarcity_score))
    elif supply <= 17:
        target = max(avg_prev + 4.0, DAILY_SALARY * 0.98, highest_prev * 0.92)
    elif supply >= 23 and hp >= 6 and no_water == 0:
        target = DAILY_SALARY * 0.42
    else:
        target = DAILY_SALARY * (0.58 + 0.25 * scarcity_score + 0.18 * urgency)
        if highest_prev > 0:
            target = max(target, min(highest_prev + 1.5, DAILY_SALARY * 1.02))

    if desperate_count >= 2 and hp >= 5 and no_water == 0:
        target *= 0.82
    if rich_count >= 2 and supply <= 18:
        target *= 1.12
    if max_opp_budget < budget * 0.55 and hp >= 5:
        target *= 0.88

    if day >= 8:
        target *= 1.12
    if day >= 9 and (hp <= 4 or supply <= 18):
        target *= 1.18

    reserve = 0.0
    if hp > 4:
        reserve = DAILY_SALARY * 0.35
    elif hp > 2:
        reserve = DAILY_SALARY * 0.15

    cap = max(0.0, budget - reserve)
    if hp <= 2 or no_water >= 2:
        cap = budget

    bid = min(target, cap if cap > 0 else budget)
    if bid < 0:
        bid = 0.0
    if hp <= 2 and bid < DAILY_SALARY * 0.9:
        bid = min(budget, DAILY_SALARY * 0.9)
    return float(round(min(budget, bid), 2))

def get_bid(day_context, my_status, opponents_status):
