def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.05)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    highest_prev_bid = 0
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

    base_bid = DAILY_SALARY * 0.55

    if my_status['hp'] <= 2:
        base_bid = DAILY_SALARY * 1.2
    elif my_status['hp'] <= 4:
        base_bid = DAILY_SALARY * 0.9
    elif my_status['hp'] >= 8:
        base_bid = DAILY_SALARY * 0.4

    if day_context['day'] >= EPISODE_DAYS - 2:
        if my_status['hp'] <= 5:
            base_bid = max(base_bid, DAILY_SALARY * 1.1)
        else:
            base_bid = max(base_bid, DAILY_SALARY * 0.8)

    if highest_prev_bid > 0:
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            if my_status['hp'] > 5:
                base_bid = min(base_bid, highest_prev_bid * 0.9)
                if base_bid < DAILY_SALARY * 0.4: base_bid = DAILY_SALARY * 0.4
            else:
                base_bid = max(base_bid, highest_prev_bid + 2.5)
        else:
            base_bid = max(base_bid, highest_prev_bid + 1.5)

    final_bid = min(my_status['budget'], max(0.01, base_bid))

    return final_bid
